-- Caller-scoped private helpers keep exposed public RPCs SECURITY INVOKER.
create or replace function private.spike_touch_presence_for_caller() returns timestamptz language plpgsql security definer set search_path=pg_catalog,public,private as $$ declare v_user_id uuid:=auth.uid(); v_visible boolean; begin if v_user_id is null then raise exception 'Authentication required'; end if; select p.presence_visible and p.account_status='active' into v_visible from public.profiles p where p.id=v_user_id; if coalesce(v_visible,false) then insert into private.spike_user_presence(user_id,last_seen_at) values(v_user_id,now()) on conflict(user_id) do update set last_seen_at=excluded.last_seen_at; return now(); end if; delete from private.spike_user_presence where user_id=v_user_id; return null; end; $$;
revoke all on function private.spike_touch_presence_for_caller() from public,anon;
grant execute on function private.spike_touch_presence_for_caller() to authenticated;
create or replace function private.spike_friends_presence_for_caller() returns table(user_id uuid,last_seen_at timestamptz,is_online boolean) language sql stable security definer set search_path=pg_catalog,public,private as $$ select friend.id,presence.last_seen_at,presence.last_seen_at>=now()-interval '150 seconds' from public.follows mine join public.follows reciprocal on reciprocal.follower_id=mine.following_id and reciprocal.following_id=mine.follower_id and reciprocal.status='accepted' join public.profiles friend on friend.id=mine.following_id join private.spike_user_presence presence on presence.user_id=friend.id where auth.uid() is not null and mine.follower_id=auth.uid() and mine.status='accepted' and friend.account_status='active' and friend.presence_visible=true and not exists(select 1 from public.blocks b where (b.blocker_id=auth.uid() and b.blocked_id=friend.id) or (b.blocker_id=friend.id and b.blocked_id=auth.uid())); $$;
revoke all on function private.spike_friends_presence_for_caller() from public,anon;
grant execute on function private.spike_friends_presence_for_caller() to authenticated;
create or replace function public.spike_touch_friends_presence() returns timestamptz language sql security invoker set search_path=pg_catalog,public,private as $$ select private.spike_touch_presence_for_caller(); $$;
create or replace function public.spike_get_friends_presence() returns table(user_id uuid,last_seen_at timestamptz,is_online boolean) language sql stable security invoker set search_path=pg_catalog,public,private as $$ select * from private.spike_friends_presence_for_caller(); $$;
revoke all on function public.spike_touch_friends_presence() from public,anon;
revoke all on function public.spike_get_friends_presence() from public,anon;
grant execute on function public.spike_touch_friends_presence() to authenticated;
grant execute on function public.spike_get_friends_presence() to authenticated;
create or replace function public.spike_block_member(p_target_id uuid) returns boolean language plpgsql security invoker set search_path=pg_catalog,public as $$ begin if auth.uid() is null then raise exception 'Authentication required'; end if; if p_target_id is null or p_target_id=auth.uid() then raise exception 'Invalid block target'; end if; insert into public.blocks(blocker_id,blocked_id) values(auth.uid(),p_target_id) on conflict(blocker_id,blocked_id) do nothing; delete from public.follows where (follower_id=auth.uid() and following_id=p_target_id) or (follower_id=p_target_id and following_id=auth.uid()); return true; end; $$;
create or replace function public.spike_unblock_member(p_target_id uuid) returns boolean language plpgsql security invoker set search_path=pg_catalog,public as $$ begin if auth.uid() is null then raise exception 'Authentication required'; end if; delete from public.blocks where blocker_id=auth.uid() and blocked_id=p_target_id; return found; end; $$;
create or replace function public.spike_remove_friend(p_target_id uuid) returns boolean language plpgsql security invoker set search_path=pg_catalog,public as $$ begin if auth.uid() is null then raise exception 'Authentication required'; end if; if p_target_id is null or p_target_id=auth.uid() then raise exception 'Invalid friend target'; end if; delete from public.follows where (follower_id=auth.uid() and following_id=p_target_id) or (follower_id=p_target_id and following_id=auth.uid()); return found; end; $$;
revoke all on function public.spike_block_member(uuid) from public,anon;
revoke all on function public.spike_unblock_member(uuid) from public,anon;
revoke all on function public.spike_remove_friend(uuid) from public,anon;
grant execute on function public.spike_block_member(uuid) to authenticated;
grant execute on function public.spike_unblock_member(uuid) to authenticated;
grant execute on function public.spike_remove_friend(uuid) to authenticated;
